import 'dart:convert';
import 'dart:io';
Future<void> main() async { final q=File('assets/source/quran.json'); if(!q.existsSync()){print('Missing assets/source/quran.json'); return;} final data=json.decode(q.readAsStringSync()) as List; Directory('assets/quran').createSync(recursive:true); final index=[]; final search=[]; for(final s in data){File('assets/quran/${s['number']}.json').writeAsStringSync(const JsonEncoder.withIndent('  ').convert(s)); index.add({'number':s['number'],'name':s['name'],'englishName':s['englishName']??'','ayahCount':(s['ayahs'] as List).length}); for(final a in s['ayahs']){search.add({'surahNumber':s['number'],'surahName':s['name'],'ayahNumber':a['number'],'text':a['text']});}} File('assets/quran_index.json').writeAsStringSync(const JsonEncoder.withIndent('  ').convert(index)); File('assets/quran_search_index.json').writeAsStringSync(const JsonEncoder.withIndent('  ').convert(search)); print('Done'); }
